    "itinerary_rows": [
      {
        "dayDate": "Day 1",
        "title": "Arrival & Shinjuku Gyoen",
        "description": "Arrive at Narita/Haneda and take the Express train to Shinjuku.\nExplore Shinjuku Gyoen National Garden to see late-blooming cherry blossoms.\nDinner at a local department store basement (depachika) for high-quality variety.",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Shinjuku_Gyoen_National_Garden_-_April_2015.jpg/1200px-Shinjuku_Gyoen_National_Garden_-_April_2015.jpg",
        "imageAlt": "Shinjuku Gyoen National Garden",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/tree.svg",
        "actionLabel": "Shinjuku Gyoen Info",
        "actionUrl": "https://www.env.go.jp/garden/shinjukugyoen/english/"
      },
      {
        "dayDate": "Day 2",
        "title": "Historical Asakusa & River Cruise",
        "description": "Visit Senso-ji, Tokyo’s oldest temple, and snack along Nakamise-dori.\nTake a futuristic \"Hotaluna\" water bus from Asakusa to Odaiba.\nEvening at the Sumida Park waterfront for city views.",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/Senso-ji_July_2021.jpg/1200px-Senso-ji_July_2021.jpg",
        "imageAlt": "Senso-ji Temple",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/bank.svg",
        "actionLabel": "Senso-ji Guide",
        "actionUrl": "https://www.senso-ji.jp/english/"
      },
      {
        "dayDate": "Day 3",
        "title": "Ueno Culture & Akihabara Anime",
        "description": "Morning at Ueno Park: Visit the Ueno Zoo or the National Museum of Nature and Science.\nAfternoon in Akihabara: Explore multi-story anime shops like Animate and Radio Kaikan.\nExperience a family-friendly themed cafe or a \"Gachapon\" capsule toy hall.",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Akihabara_at_Night.jpg/1200px-Akihabara_at_Night.jpg",
        "imageAlt": "Akihabara at Night",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/controller.svg",
        "actionLabel": "Ueno Zoo Tickets",
        "actionUrl": "https://www.tokyo-zoo.net/english/ueno/"
      },
      {
        "dayDate": "Day 4",
        "title": "Ghibli Magic & Inokashira Park",
        "description": "Morning at the Ghibli Museum in Mitaka (requires booking exactly one month prior).\nPicnic lunch and swan boats at the adjacent Inokashira Park.\nEvening walk through the trendy shops of Kichijoji.",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/Ghibli_Museum_Totoro.jpg/1200px-Ghibli_Museum_Totoro.jpg",
        "imageAlt": "Ghibli Museum Totoro",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/stars.svg",
        "actionLabel": "Ghibli Museum",
        "actionUrl": "https://www.ghibli-museum.jp/en/"
      },
      {
        "dayDate": "Day 5",
        "title": "Harajuku Trends & Shibuya Crossing",
        "description": "Morning at Meiji Jingu Shrine, a peaceful forest in the heart of the city.\nWalk through Takeshita Street for colorful street food and Harajuku fashion.\nWitness the Shibuya Crossing and view the city from the Shibuya Sky observatory.",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b8/Shibuya_Crossing_2018.jpg/1200px-Shibuya_Crossing_2018.jpg",
        "imageAlt": "Shibuya Crossing",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/camera.svg",
        "actionLabel": "Shibuya Sky Booking",
        "actionUrl": "https://www.shibuya-scramble-square.com/sky/"
      },
      {
        "dayDate": "Day 6",
        "title": "Digital Art & Giant Robots in Odaiba",
        "description": "Morning at teamLab Borderless or Planets for immersive digital art.\nVisit the life-sized Unicorn Gundam Statue outside DiverCity Tokyo Plaza.\nAfternoon at Miraikan",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/TeamLab_Border_Digital_Art_Museum.jpg/1200px-TeamLab_Border_Digital_Art_Museum.jpg",
        "imageAlt": "TeamLab Borderless Digital Art Museum",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/robot.svg",
        "actionLabel": null,
        "actionUrl": null
      }
    ]
  },
